import sailpoint.object.Form;
Object disablePassword = field.getValue();

String requiredAttribute = "|password|FORCE_PWD_CHG_ON_NEXT_LOGON|";

Form.Section section = form.getSection("Password Authentication");

if (section != null && section.getFields() != null ) {

for (Object field : section.getFields()) {
String name = field.getName();
if (name != null && name.indexOf(":") > 0 ) {
String[] nameKeys = name.split(":");
if ( requiredAttribute.contains("|" + nameKeys[2] + "|") ) {
if(null != disablePassword && disablePassword.toString().equals("true")) {
field.setRequired(false);
field.setHidden(true);
}
else {
field.setRequired(true);
field.setHidden(false);
}
}
}
}
}
return false;

import sailpoint.object.Form;
Object selectKerberos = field.getValue();

String requiredAttribute = "|EXTERNAL_IDENTITY_KERBEROS|";

Form.Section section = form.getSection("Kerberos Authentication");

if (section != null && section.getFields() != null ) {
for (Object field : section.getFields()) {
String name = field.getName();
if (name != null && name.indexOf(":") > 0 ) {
String[] nameKeys = name.split(":");
if ( requiredAttribute.contains("|" + nameKeys[2] + "|") ) {
if(null != selectKerberos &&
selectKerberos.toString().equals("true")) {
field.setRequired(true);
field.setHidden(false);
}
else {
field.setRequired(false);
field.setHidden(true);
}
}
}
}
}
return false;

